class Solution {
public:
    ListNode* insertGreatestCommonDivisors(ListNode* head) {
        if (!head || !head->next) return head;
        ListNode* cur = head;
        while (cur->next) {
            int g = gcd(cur->val, cur->next->val);
            ListNode* node = new ListNode(g, cur->next);
            cur->next = node;
            cur = node->next;
        }
        return head;
    }
private:
    int gcd(int a, int b) {
        while (b) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
};
